    static func info(_ name: String) -> LogMsgInfo? { messages[name] }
    static func fieldHelp(_ msg: String, _ field: String) -> String? { messages[msg]?.fields[field] }

    /// Пояснення пари підсистема/код з повідомлення ERR.
    static func errMeaning(subsys: Int, code: Int) -> String {
        let failsafe: Set<Int> = [5, 6, 7, 8, 9, 17, 20, 21, 23, 24, 26, 27, 29, 31]
        if failsafe.contains(subsys) { return code == 0 ? String(localized: "Збій усунуто: failsafe «\(DFLog.errSubsys(subsys))» знято.") : String(localized: "Спрацював failsafe «\(DFLog.errSubsys(subsys))». Перевірте причину: зв'язок, батарея, GPS чи межі геозони.") }
        switch subsys {
        case 12: return code == 1 ? "Виявлено падіння (crash check): апарат різко втратив керування або перекинувся." : "Втрата керування (thrust loss / loss of control)."
        case 16: return code == 0 ? "Перевірку EKF знято." : "Перевірка EKF: розбіжність сенсорів, фільтр втрачає надійність."
        case 3: return code == 2 ? "Компас: не вдалося прочитати дані або він несправний." : (code == 1 ? "Компас: не вдалося ініціалізувати." : String(localized: "Компас: подія (код \(code))."))
        case 2: return code == 0 ? "Приймач: відновлено." : "Приймач: проблема зі зв'язком або сигналом."
        case 11: return code == 2 ? "GPS: глітч (стрибок позиції)." : (code == 0 ? "GPS: помилку усунуто." : String(localized: "GPS: подія (код \(code))."))
        case 18: return String(localized: "Барометр: помилка (код \(code)).")
        case 10: return String(localized: "Режим польоту: не вдалося перемкнути (код — спроба режиму \(code)).")
        case 30: return String(localized: "Внутрішня помилка програми автопілота (код \(code)). Повідомте розробників з логом.")
        default: return String(localized: "Підсистема «\(DFLog.errSubsys(subsys))», код \(code). Довідка: ArduPilot → Log Messages → ERR.")
        }
    }
}

